const FALLBACK_FREIGHT_USD: Record<string, number> = { cj: 15, printify: 10.39, gelato: 12, printful: 12 };
const NOK_PER_USD = 10.8;
const NET = 1 / 1.25 - 0.03;

export type ProfitLine = { provider: string; ref?: string; costUsd: number; ids?: Record<string, any>; quantity: number; nok: number };

export function unitCostUsd(l: ProfitLine): number {
  const p = String(l.provider || "").toLowerCase(); const ids = l.ids || {};
  const known = p === "cj"
    ? UNIT_COST_USD["cj|" + (ids.cj_vid || "")] || UNIT_COST_USD["cj|" + (ids.cj_pid || l.ref || "")]
    : UNIT_COST_USD[`${p}|${ids.printify_product_id || ""}|${ids.printify_variant_id || ""}`] || UNIT_COST_USD[`${p}|${l.ref || ""}`];
  return Math.max(Number(known) || 0, (Number(l.costUsd) || 0) + (known ? 0 : FALLBACK_FREIGHT_USD[p] ?? 15));
}

/** Shipping (NOK, whole kroner) so the order never loses money. baseNok = 0 (free) or 79 (normal). */
export function profitSafeShippingNok(lines: ProfitLine[], baseNok: number, normalNok = 79) {
  const revenue = lines.reduce((s, l) => s + l.nok * l.quantity, 0);
  const cost = lines.reduce((s, l) => s + unitCostUsd(l) * l.quantity, 0) * NOK_PER_USD;
  const profitAt = (ship: number) => (revenue + ship) * NET - cost;
  let ship = baseNok;
  if (profitAt(ship) < 0) ship = Math.max(normalNok, Math.ceil((cost / NET - revenue) * 1) );
  if (profitAt(ship) < 0) ship += 1;
  return { shippingNok: ship, profitNok: Math.round(profitAt(ship) * 100) / 100, raised: ship !== baseNok };
}
